sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mode;
uniform float amzp_gizmoSize;
uniform float amzp_gridY;
uniform float amzp_gridStep;
uniform float amzp_gridCount;
uniform float amzp_lineWidth;
layout(color) uniform half4 amzp_gridColor;
uniform float amzp_fxAlpha;
uniform float amzp_overdrawOn;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    float gLine;
    float2 gQ;
    float gPsc;
    float segV(float3 a, float3 b) {
        float nz = 1.0;
        if (a.z < nz && b.z < nz) return 0.0;
        if (a.z < nz) a = mix(a, b, (nz - a.z) / (b.z - a.z));
        if (b.z < nz) b = mix(b, a, (nz - b.z) / (a.z - b.z));
        float4 ha = nmProj * float4(a, 1.0);
        float4 hb = nmProj * float4(b, 1.0);
        float2 pa = ha.xy / ha.w * gPsc;
        float2 pb = hb.xy / hb.w * gPsc;
        float2 pq = gQ - pa, ba = pb - pa;
        float h = clamp(dot(pq, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
        float d = length(pq - ba * h);
        return 1.0 - smoothstep(gLine * 0.5, gLine * 0.5 + 1.0, d);
    }
    void nmMain() {
        float4 orig = amzTexture(0, amzScreenNorm());
        gPsc = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        gQ = pix - screen.zw * 0.5;
        gLine = amzp_lineWidth * gPsc;
        float3 L = float3(0.0);
        if (int(amzp_mode) != 1) {
            float4x4 MV = nmView * nmModel;
            float s = amzp_gizmoSize;
            float3 o = (MV * float4(0.0, 0.0, 0.0, 1.0)).xyz;
            L += float3(1.0, 0.2, 0.2) * segV(o, (MV * float4(s, 0.0, 0.0, 1.0)).xyz);
            L += float3(0.2, 1.0, 0.2) * segV(o, (MV * float4(0.0, s, 0.0, 1.0)).xyz);
            L += float3(0.3, 0.5, 1.0) * segV(o, (MV * float4(0.0, 0.0, -s, 1.0)).xyz);
            float c = s * 0.5;
            float3 p0 = (MV * float4(-c, -c, 0.0, 1.0)).xyz, p1 = (MV * float4(c, -c, 0.0, 1.0)).xyz;
            float3 p2 = (MV * float4(c, c, 0.0, 1.0)).xyz, p3 = (MV * float4(-c, c, 0.0, 1.0)).xyz;
            float3 q0 = (MV * float4(-c, -c, -s, 1.0)).xyz, q1 = (MV * float4(c, -c, -s, 1.0)).xyz;
            float3 q2 = (MV * float4(c, c, -s, 1.0)).xyz, q3 = (MV * float4(-c, c, -s, 1.0)).xyz;
            float e = segV(p0, p1) + segV(p1, p2) + segV(p2, p3) + segV(p3, p0)
                    + segV(q0, q1) + segV(q1, q2) + segV(q2, q3) + segV(q3, q0)
                    + segV(p0, q0) + segV(p1, q1) + segV(p2, q2) + segV(p3, q3);
            L += float3(1.0, 0.85, 0.3) * min(e, 1.0) * 0.8;
        }
        if (int(amzp_mode) != 0) {
            float n = floor(amzp_gridCount + 0.5);
            float st = max(amzp_gridStep, 1.0);
            float ext = n * st;
            float g = 0.0;
            for (int i = -20; i <= 20; i++) {
                float fi = float(i);
                if (abs(fi) > n) continue;
                float3 a = (nmView * float4(fi * st, amzp_gridY, -ext, 1.0)).xyz;
                float3 b = (nmView * float4(fi * st, amzp_gridY, ext, 1.0)).xyz;
                g += segV(a, b);
                a = (nmView * float4(-ext, amzp_gridY, fi * st, 1.0)).xyz;
                b = (nmView * float4(ext, amzp_gridY, fi * st, 1.0)).xyz;
                g += segV(a, b);
            }
            L += amzp_gridColor.rgb * min(g, 1.0) * 0.85;
        }
        L *= clamp(amzp_fxAlpha, 0.0, 1.0);
        float la = clamp(max(L.r, max(L.g, L.b)), 0.0, 1.0);
        amzOutput = float4(clamp(L, 0.0, 1.0) + orig.rgb * (1.0 - la), la + orig.a * (1.0 - la));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
